using namespace Helpers;

void CreateShaderTable_01(ID3D12StateObjectProperties* stateObjectProperties, byte* output)
{
    std::copy_n(static_cast<const byte*>(stateObjectProperties->GetShaderIdentifier(LR"(DefaultMiss)")), D3D12_SHADER_IDENTIFIER_SIZE_IN_BYTES, &output[0]);
}

